arguments.command:
cd /workspace/outputs && python3 -c "
import json
rows=[json.loads(l) for l in open('wandb-history.jsonl') if l.strip()]
print('step | global_step | val_acc | score_mean | resp_len_mean | resp_clip | aborted | entropy | kl_loss | grad_norm | pg_clipfrac | ppo_kl')
for r in rows:
    def g(k): 
        v=r.get(k); 
        return '' if v is None else (f'{v:.4f}' if isinstance(v,float) else str(v))
    print(' | '.join([g('_step'), g('training/global_step'), g('val-core/openai/gsm8k/acc/mean@1'), g('critic/score/mean'), g('response_length/mean'), g('response_length/clip_ratio'), g('response/aborted_ratio'), g('actor/entropy'), g('actor/kl_loss'), g('actor/grad_norm'), g('actor/pg_clipfrac'), g('actor/ppo_kl')]))
"
